#include "sim/recipes.h"
#include <fstream>
#include <nlohmann/json.hpp>
#include <set>
#include <stdexcept>
namespace nuc::sim {
void RecipeBook::add(Recipe recipe){if(recipe.id.empty()||recipe.craft_ticks==0||recipe.inputs.empty()||recipe.outputs.empty())throw std::invalid_argument("recipe requires id, inputs, outputs, and positive craft_ticks");auto validate=[](const auto& list){std::set<ItemId> ids;for(const auto& a:list)if(a.item==0||a.count==0||!ids.insert(a.item).second)throw std::invalid_argument("recipe item IDs must be nonzero, unique, and counts positive");};validate(recipe.inputs);validate(recipe.outputs);auto key=recipe.id;if(!recipes_.emplace(std::move(key),std::move(recipe)).second)throw std::invalid_argument("duplicate recipe id");}
void RecipeBook::load(const std::filesystem::path& path){std::ifstream in(path);if(!in)throw std::runtime_error("cannot open recipes: "+path.string());nlohmann::json root;try{in>>root;}catch(const nlohmann::json::exception& e){throw std::runtime_error("invalid recipes JSON: "+std::string(e.what()));}if(!root.is_array())throw std::runtime_error("recipes root must be an array");std::unordered_map<std::string,Recipe> parsed;for(const auto& j:root){if(!j.is_object()||!j.contains("id")||!j["id"].is_string())throw std::runtime_error("recipe missing string id");Recipe r;r.id=j["id"].get<std::string>();if(!j.contains("craft_ticks")||!j["craft_ticks"].is_number_integer()||j["craft_ticks"].get<std::int64_t>()<=0)throw std::runtime_error("recipe craft_ticks must be a positive integer");r.craft_ticks=j["craft_ticks"].get<std::uint32_t>();auto parse=[](const nlohmann::json& arr,std::vector<ItemAmount>& out){if(!arr.is_array())throw std::runtime_error("recipe inputs/outputs must be arrays");for(const auto& item:arr){if(!item.is_object()||!item.contains("item")||!item.contains("count")||!item["item"].is_number_integer()||!item["count"].is_number_integer()||item["item"].get<std::int64_t>()<=0||item["count"].get<std::int64_t>()<=0)throw std::runtime_error("recipe item requires positive integer item and count");out.push_back({item["item"].get<ItemId>(),item["count"].get<std::uint32_t>()});}};if(!j.contains("inputs")||!j.contains("outputs"))throw std::runtime_error("recipe missing inputs or outputs");parse(j["inputs"],r.inputs);parse(j["outputs"],r.outputs);if(!parsed.emplace(r.id,r).second)throw std::runtime_error("duplicate recipe id: "+r.id);}auto previous=std::move(recipes_);recipes_.clear();try{for(auto& pair:parsed)add(std::move(pair.second));}catch(...){recipes_=std::move(previous);throw;}}
const Recipe* RecipeBook::find(const std::string& id) const noexcept{auto it=recipes_.find(id);return it==recipes_.end()?nullptr:&it->second;}
bool RecipeBook::can_craft(const Recipe& r,const Inventory& inv) const noexcept{for(const auto& a:r.inputs)if(inv.count(a.item)<a.count)return false;return true;}
bool RecipeBook::can_output(const Recipe& r,const Inventory& inv) const noexcept{for(const auto& a:r.outputs)if(!inv.can_insert(ItemStack{a.item,a.count,64}))return false;return true;}
bool RecipeBook::consume_inputs(const Recipe& r,Inventory& inv) const{if(!can_craft(r,inv))return false;for(const auto& a:r.inputs)if(inv.remove(a.item,a.count)!=a.count)return false;return true;}
bool RecipeBook::produce_outputs(const Recipe& r,Inventory& inv) const{if(!can_output(r,inv))return false;for(const auto& a:r.outputs)if(inv.insert(ItemStack{a.item,a.count,64})!=a.count)return false;return true;}
}
